from math import factorial

def mod_inverse(a, p):
    return pow(a, p - 2, p)

def binomial_coefficient(n, k, p):
    if k > n:
        return 0
    num = factorial(n) % p
    den = (factorial(k) * factorial(n - k)) % p
    return (num * mod_inverse(den, p)) % p

def count_permutations_with_runs(n, k, p):
    def stirling_second_kind(n, k, p):
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            for j in range(1, k + 1):
                dp[i][j] = (dp[i - 1][j - 1] + j * dp[i - 1][j]) % p
        return dp[n][k]

    def bell_number(n, k, p):
        bell = [0] * (n + 1)
        bell[0] = 1
        for i in range(1, n + 1):
            bell[i] = sum((binomial_coefficient(i - 1, j, p) * bell[j]) % p for j in range(k + 1)) % p
        return bell[n]

    total_permutations = factorial(n) % p
    result = 0
    sign = 1
    for i in range(1, n // k + 1):
        result = (result + sign * (total_permutations - bell_number(n, k * i, p))) % p
        sign *= -1

    return result

